{
  "episode_title": "The Floor That Isn't",
  "logline": "Voss attempts to document the elevator's illogical behavior while Mara desperately tries to maintain the facade of normalcy.",
  "tone": [
    "surreal",
    "comedy"
  ],
  "target_duration_seconds": 50.0,
  "active_characters": [
    "voss",
    "mara",
    "ellis"
  ],
  "primary_location": "floor_3_hallway",
  "central_goal": {
    "character": "voss",
    "goal": "find a code violation"
  },
  "beats": [
    {
      "id": "beat_1",
      "narrative_purpose": "Hook: The elevator dings and lights flicker aggressively.",
      "blocking": "Voss stands at the elevator doors; Mara stands by the maintenance panel.",
      "visible_action": "The hallway lights flicker rapidly as the elevator dings.",
      "intended_reaction": "Voss looks up in confusion; Mara sighs heavily.",
      "camera_purpose": "establish the impossible event",
      "performance_intent": "bureaucratic confusion",
      "target_start_second": 0.0,
      "actions": [
        {
          "actor": "voss",
          "action": "look_at",
          "target": "elevator"
        },
        {
          "actor": "voss",
          "action": "speak",
          "text": "This elevator just announced arrival at Floor Negative Twelve. That is highly irregular."
        },
        {
          "actor": "mara",
          "action": "flicker_lights"
        },
        {
          "actor": "mara",
          "action": "speak",
          "text": "The wiring in this building is ancient and prone to very strange glitches."
        }
      ],
      "camera_intent": {
        "type": "establish",
        "subject": "voss"
      },
      "completion_condition": {
        "type": "dialogue_finished"
      }
    },
    {
      "id": "beat_2",
      "narrative_purpose": "Ellis enters to escalate the curiosity.",
      "blocking": "Ellis enters from apartment 3b; Voss turns toward him.",
      "visible_action": "Ellis rushes toward the elevator doors with intense curiosity.",
      "intended_reaction": "Voss steps back to make room; Mara looks stressed.",
      "camera_purpose": "introduce new character and tension",
      "performance_intent": "eager, frantic",
      "target_start_second": 8.0,
      "actions": [
        {
          "actor": "ellis",
          "action": "enter_room"
        },
        {
          "actor": "ellis",
          "action": "approach",
          "target": "elevator"
        },
        {
          "actor": "ellis",
          "action": "speak",
          "text": "Did you hear that? The elevator is singing in a language I don't know!"
        },
        {
          "actor": "voss",
          "action": "turn_toward",
          "target": "ellis"
        },
        {
          "actor": "voss",
          "action": "speak",
          "text": "Singing is not a recognized feature in the standard building occupancy code."
        }
      ],
      "camera_intent": {
        "type": "conversation",
        "subject": "ellis"
      },
      "completion_condition": {
        "type": "dialogue_finished"
      }
    },
    {
      "id": "beat_3",
      "narrative_purpose": "Mara tries to deflect the investigation.",
      "blocking": "Mara moves toward Ellis to block his view of the elevator.",
      "visible_action": "Mara gestures wildly toward the maintenance panel.",
      "intended_reaction": "Ellis leans around her; Voss takes out a notepad.",
      "camera_purpose": "focus on Mara's evasion",
      "performance_intent": "desperate, strained",
      "target_start_second": 18.0,
      "actions": [
        {
          "actor": "mara",
          "action": "move_to",
          "target": "ellis"
        },
        {
          "actor": "mara",
          "action": "speak",
          "text": "It is just air pressure escaping the shaft. Please stop bothering the inspector."
        },
        {
          "actor": "voss",
          "action": "pick_up"
        },
        {
          "actor": "voss",
          "action": "speak",
          "text": "Air pressure does not typically recite epic poetry in a minor key, Madam."
        }
      ],
      "camera_intent": {
        "type": "speaker_closeup",
        "subject": "mara"
      },
      "completion_condition": {
        "type": "dialogue_finished"
      }
    },
    {
      "id": "beat_4",
      "narrative_purpose": "Physical escalation: the elevator doors open.",
      "blocking": "The elevator doors open to reveal a glowing purple light.",
      "visible_action": "The elevator doors slide open with a heavy thud.",
      "intended_reaction": "Voss stares blankly; Ellis gasps loudly.",
      "camera_purpose": "reveal the anomaly",
      "performance_intent": "shocked",
      "target_start_second": 28.0,
      "actions": [
        {
          "actor": "ellis",
          "action": "shout",
          "text": "Look! The interior looks like a nebula made of liquid grape soda!"
        },
        {
          "actor": "voss",
          "action": "inspect",
          "target": "elevator"
        },
        {
          "actor": "voss",
          "action": "speak",
          "text": "I am marking this down as an unauthorized atmospheric modification in the hallway."
        },
        {
          "actor": "mara",
          "action": "speak",
          "text": "It is just a very aggressive mood lighting installation for the lobby."
        }
      ],
      "camera_intent": {
        "type": "reveal",
        "subject": "elevator"
      },
      "completion_condition": {
        "type": "dialogue_finished"
      }
    },
    {
      "id": "beat_5",
      "narrative_purpose": "Voss pushes for a violation.",
      "blocking": "Voss approaches the elevator; Mara follows him closely.",
      "visible_action": "Voss points a pen at the glowing elevator interior.",
      "intended_reaction": "Mara winces; Ellis tries to peek closer.",
      "camera_purpose": "tension push on the confrontation",
      "performance_intent": "determined, bureaucratic",
      "target_start_second": 38.0,
      "actions": [
        {
          "actor": "voss",
          "action": "point_at",
          "target": "elevator"
        },
        {
          "actor": "voss",
          "action": "speak",
          "text": "This violates section four regarding non-standard dimensions in public transit areas."
        },
        {
          "actor": "mara",
          "action": "speak",
          "text": "We can fix the dimensions by Monday if you just sign this waiver."
        },
        {
          "actor": "ellis",
          "action": "speak",
          "text": "Can I go inside? I want to see if it tastes like grapes!"
        }
      ],
      "camera_intent": {
        "type": "tension_push",
        "subject": "voss"
      },
      "completion_condition": {
        "type": "dialogue_finished"
      }
    },
    {
      "id": "beat_6",
      "narrative_purpose": "Payoff: The elevator pulls them in or slams shut.",
      "blocking": "The elevator doors slam shut on Voss's notepad.",
      "visible_action": "The elevator doors close violently; the lights flicker one last time.",
      "intended_reaction": "Voss looks at his empty hands; Mara facepalms.",
      "camera_purpose": "cliffhanger hold",
      "performance_intent": "exhausted",
      "target_start_second": 46.0,
      "actions": [
        {
          "actor": "voss",
          "action": "speak",
          "text": "My clipboard! The elevator has consumed my official documentation and my dignity!"
        },
        {
          "actor": "mara",
          "action": "speak",
          "text": "I told you the maintenance was going to be a real nightmare today."
        },
        {
          "actor": "ellis",
          "action": "speak",
          "text": "At least the grape soda smell is actually quite pleasant, don't you think?"
        },
        {
          "actor": "mara",
          "action": "sigh"
        }
      ],
      "camera_intent": {
        "type": "cliffhanger_hold",
        "subject": "mara"
      },
      "completion_condition": {
        "type": "dialogue_finished"
      }
    }
  ],
  "payoff": "The elevator doors slam shut, leaving Voss without his clipboard and Mara contemplating her life choices."
}

